INSERT INTO public.products (id, name, description, min_amount, max_amount, min_term, max_term, base_rate, tags)
SELECT v.id::uuid, v.name, v.description, v.min_amount, v.max_amount, v.min_term, v.max_term, v.base_rate, v.tags
FROM (VALUES
    ('10000000-0000-0000-0000-000000000001', 'Оборотный кредит', 'Лучше всего под закупку товара и пополнение оборотных средств', 100000, 30000000, 3, 36, 22.0, '["Без залога", "Онлайн"]'),
    ('10000000-0000-0000-0000-000000000002', 'Овердрафт', 'Для краткосрочных кассовых разрывов', 100000, 5000000, 1, 12, 24.0, '["Без залога", "Возобновляемый"]'),
    ('10000000-0000-0000-0000-000000000003', 'Инвестиционный кредит', 'На покупку оборудования и транспорта', 500000, 100000000, 12, 84, 20.0, '["С залогом"]'),
    ('10000000-0000-0000-0000-000000000004', 'Кредит с господдержкой', 'Поручительство Корпорации МСП', 100000, 50000000, 3, 36, 19.5, '["Без залога", "Госпрограмма"]')
) AS v(id, name, description, min_amount, max_amount, min_term, max_term, base_rate, tags)
WHERE NOT EXISTS (SELECT 1 FROM public.products p WHERE p.name = v.name);

