INSERT INTO public.managers (id, name, role)
SELECT v.id::uuid, v.name, v.role
FROM (VALUES
    ('20000000-0000-0000-0000-000000000001', 'Анна Ковалева', 'credit_analyst'),
    ('20000000-0000-0000-0000-000000000002', 'Сергей Морозов', 'senior_analyst')
) AS v(id, name, role)
WHERE NOT EXISTS (SELECT 1 FROM public.managers m WHERE m.id = v.id::uuid);
